import {SCENES,sampleAt,clock,beatScale} from './core.js';
const $=id=>document.getElementById(id);
const state={scene:'heart',data:null,workout:0,time:0,playing:false,reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,speed:30,last:0,gap:false,night:0,experiment:2,case:0,filter:'all',braintrust:null};
let w;
const scenes={
 heart:{chapter:'01 / CARDIAC REPLAY',title:'Feel the <br><em>recorded rhythm.</em>',intro:'Move through a workout. The heart follows the recorded rate; a missing signal stays missing.',label:'THE RHYTHM OF EFFORT',context:'RECORDED SESSION REPLAY'},
 trail:{chapter:'02 / THE BURRO TRAIL',title:'Every pause <br><em>has a place.</em>',intro:'Follow a recorded route with a burro as your playhead. Slow motion is an observation, not an explanation.',label:'A JOURNEY, NOT A LINE CHART',context:'NORMALIZED ROUTE REPLAY'},
 recovery:{chapter:'03 / RECORDED REST',title:'A sky full <br><em>of quiet nights.</em>',intro:'One luminous orb for each recorded night. Select a night to see its sleep evidence, without a readiness score.',label:'THIRTY NIGHTS, ONE SKY',context:'RECORDED SLEEP · NO RECOVERY INFERENCE'},
 agents:{chapter:'04 / AGENT CONSTELLATION',title:'Let the failures <br><em>be visible.</em>',intro:'Each star is one real Braintrust evaluation case. Explore the same questions across three agent variants.',label:'A CONSTELLATION OF EVIDENCE',context:'40 SYNTHETIC CASES / EXPERIMENT'}
};
function setText(id,value){$(id).textContent=value;}
function formatHours(h){return Number.isFinite(h)?`${Math.floor(h)}h ${Math.round((h%1)*60).toString().padStart(2,'0')}m`:'Not recorded';}
function setPlay(value){state.playing=value;$('play').textContent=value?'Ⅱ':'▶';$('play').setAttribute('aria-label',value?'Pause replay':'Play replay');}
function setReduced(value){state.reduced=value;document.body.classList.toggle('reduced',value);$('motion').setAttribute('aria-pressed',String(value));$('motion').textContent=value?'Motion reduced':'Reduce motion';}
function currentHR(){return state.gap&&state.time>=600&&state.time<=720?null:sampleAt(w?.hr||[],state.time);}
function facts(l1,v1,l2,v2){setText('factLabel1',l1);setText('fact1',v1);setText('factLabel2',l2);setText('fact2',v2);}
function updateHeart(){const sample=currentHR();setText('bpm',sample?Math.round(sample.bpm):'—');setText('heartState',sample?'Signal available':'No recent sample');setText('sampleAge',sample?`${Math.round(state.time-sample.t)}s since sample`:'No rate is invented');$('heartScene').classList.toggle('dimmed',!sample);facts('RECORDED DISTANCE',w?.distance==null?'Not recorded':w.distance.toFixed(1)+' km','ELAPSED TIME',clock(w?.duration));setText('interpretation',state.gap?'Demo gap: heart-rate samples are hidden from 10:00–12:00. The heartbeat stops and the value becomes unavailable.':'The pulse follows the selected BPM at wall-clock rate. Replay speed moves through samples faster; it does not multiply the heartbeat.');}
function drawTrail(){const box=$('trailScene');box.replaceChildren();if(!w?.route.length){box.innerHTML='<p class="scene-placeholder">No route was recorded for this session.<br>A path will not be invented.</p>';return;}const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 1000 700');svg.classList.add('trail-map');const coords=w.route.map(p=>[p.x*800+100,p.y*490+105]);let segment='';w.route.forEach((p,i)=>{segment+=(i===0||p.t-w.route[i-1].t>30?'M':'L')+coords[i].join(',')+' ';});const path=document.createElementNS(ns,'path');path.setAttribute('d',segment);svg.append(path);const progress=document.createElementNS(ns,'path');progress.classList.add('travelled');progress.id='trailProgress';svg.append(progress);const point=document.createElementNS(ns,'circle');point.setAttribute('r','5');point.classList.add('trail-pointer');point.id='trailPoint';svg.append(point);box.append(svg);const marker=document.createElement('img');marker.src='assets/burro.jpg';marker.alt='Illustrative burro marking the latest recorded route position';marker.className='burro-marker';marker.id='burro';box.append(marker);const label=document.createElement('span');label.className='trail-orientation';label.textContent='ROUTE SHAPE / NO BASEMAP';box.append(label);const meta=document.createElement('div');meta.className='trail-state';meta.innerHTML='<span class="micro">CURRENT OBSERVATION</span><strong id="trailState">Moving</strong><span id="trailSpeed"></span>';box.append(meta);const foot=document.createElement('span');foot.className='scene-footnote';foot.textContent='Illustrative burro; no animal sensor data. GPS gaps are not joined.';box.append(foot);}
function updateTrail(){if(!w)return;const p=sampleAt(w.route,state.time);const stopped=w.stops.some(s=>state.time>=s.start&&state.time<=s.end);if($('trailState')){setText('trailState',!p?'Signal gap':stopped?'A slow moment':'On the trail');setText('trailSpeed',p?.speed!=null?`${(p.speed*3.6).toFixed(1)} km/h · GPS-derived`:'Speed unavailable');$('burro').hidden=!p;$('trailPoint').style.opacity=p?'1':'0';if(p){const stage=$('trailScene'), scale=Math.min(stage.clientWidth/1000,stage.clientHeight/700),offX=(stage.clientWidth-1000*scale)/2,offY=(stage.clientHeight-700*scale)/2;const x=p.x*800+100,y=p.y*490+105;$('burro').style.left=(offX+x*scale)+'px';$('burro').style.top=(offY+y*scale)+'px';$('trailPoint').setAttribute('cx',x);$('trailPoint').setAttribute('cy',y);}let d='';w.route.filter(p=>p.t<=state.time).forEach((p,i,arr)=>{d+=(i===0||p.t-arr[i-1].t>30?'M':'L')+(p.x*800+100)+','+(p.y*490+105)+' ';});$('trailProgress').setAttribute('d',d);}facts('RECORDED DISTANCE',w.distance==null?'Not recorded':w.distance.toFixed(1)+' km','LOW-MOTION CANDIDATES',clock(w.stops.reduce((s,x)=>s+x.end-x.start,0)));setText('interpretation',!p?'No recent GPS position. The burro is hidden until another accepted observation arrives.':stopped?'At least 30 seconds below 0.5 m/s was detected here. A stop candidate does not tell us what the runner or burro was doing.':'The playhead uses the latest accepted GPS observation. Position is held until the next observation; gaps over 30 seconds stay empty.');}
function drawNights(){const box=$('recoveryScene');box.innerHTML='<div class="sky-head"><strong id="nightDuration">—</strong><span id="nightDate"></span></div><div class="night-orbs" id="nights"></div><span class="scene-footnote">One orb per recorded night. Orb area encodes time asleep.</span>';for(const [i,n] of state.data.nights.entries()){const b=document.createElement('button');b.className='night';b.setAttribute('aria-label',`${n.day}: ${formatHours(n.total_h)} asleep`);b.setAttribute('aria-pressed',String(i===state.night));const orb=document.createElement('span');orb.className='orb';const d=13*Math.sqrt(Math.max(0,n.total_h));orb.style.width=d+'px';orb.style.height=d+'px';const date=document.createElement('span');date.className='date';date.textContent=n.day.slice(5);b.append(orb,date);b.onclick=()=>{state.night=i;update();};$('nights').append(b);}}
function updateNight(){const n=state.data.nights[state.night];if(!n){setText('nightDuration','No nights');setText('nightDate','No sleep observations in this snapshot');facts('TIME ASLEEP','—','STAGED SLEEP','—');return;}setText('nightDuration',formatHours(n.total_h));setText('nightDate',n.day);[...$('nights').children].forEach((b,i)=>b.setAttribute('aria-pressed',String(i===state.night)));facts('RECORDED NIGHT',n.day.slice(5),'TIME ASLEEP',formatHours(n.total_h));setText('interpretation','Sleep intervals are unioned from one source per night. A brighter or larger orb does not mean better recovery or better health.');$('extraControls').innerHTML='<p class="sky-stages">Deep <b>'+formatHours(n.deep_h)+'</b><br>REM <b>'+formatHours(n.rem_h)+'</b><br>Core <b>'+formatHours(n.core_h)+'</b></p>';setText('clock',String(state.night+1).padStart(2,'0'));setText('duration','/ '+state.data.nights.length+' nights');$('seek').value=state.night;}
function currentExperiment(){return state.braintrust?.experiments[state.experiment];}
function drawCases(){const e=currentExperiment();if(!e)return;const box=$('agentsScene');box.innerHTML='<div class="constellation-core"><strong id="passRate"></strong><span>CASES PASSED<br>DEVELOPMENT SET</span></div><div class="stars" id="stars"></div><div class="case-legend"><span>● Passed</span><span>● Failed</span><span>● Blocked safely</span></div>';const max=e.cases.length;for(const [i,c] of e.cases.entries()){const b=document.createElement('button');b.className='case-star'+(!c.case_pass?' failed':c.status==='blocked'?' blocked':'');b.dataset.case=c.case_id;b.setAttribute('aria-label',`${c.case_id}: ${c.case_pass?'passed':'failed'}, ${c.question}`);b.setAttribute('aria-pressed',String(i===state.case));b.textContent=String(i+1).padStart(2,'0');const ring=i<16?0:1,count=ring?max-16:16,j=ring?i-16:i,a=j/count*Math.PI*2-Math.PI/2+(ring?.075:0),r=ring?45:29;b.style.left=50+Math.cos(a)*r+'%';b.style.top=50+Math.sin(a)*r+'%';b.hidden=state.filter==='failed'&&c.case_pass||state.filter==='blocked'&&c.status!=='blocked';b.onclick=()=>{state.case=i;update();};$('stars').append(b);}setText('passRate',Math.round(e.pass_rate*100)+'%');}
function updateCase(){const e=currentExperiment();if(!e)return;const matches=c=>state.filter==='all'||state.filter==='failed'&&!c.case_pass||state.filter==='blocked'&&c.status==='blocked';if(!e.cases.some(matches)){facts('PERSISTED CASES',e.verified_case_count+' / '+e.case_count,'MATCHING CASES','0');setText('interpretation','No '+state.filter+' cases in this experiment. All 40 development cases remain available through All cases.');$('extraControls').replaceChildren();setText('clock','—');setText('duration','/ '+e.cases.length+' cases');return;}if(!matches(e.cases[state.case]))state.case=e.cases.findIndex(matches);const c=e.cases[state.case];[...$('stars').children].forEach((b,i)=>b.setAttribute('aria-pressed',String(i===state.case)));facts('PERSISTED CASES',e.verified_case_count+' / '+e.case_count,'THIS CASE',c.case_pass?'Passed':'Failed');setText('interpretation',c.question);$('extraControls').replaceChildren();const details=document.createElement('div');for(const [key,value] of [['Case',c.case_id],['Route',c.route??'Unreported'],['Outcome',c.status??'Unreported'],['Latency',c.latency_ms==null?'Unavailable':c.latency_ms.toFixed(1)+' ms'],['Model tokens',c.tokens==null?'Unreported':String(c.tokens)]]){const p=document.createElement('p');p.className='case-detail';p.textContent=key+': ';const strong=document.createElement('strong');strong.textContent=value;p.append(strong);details.append(p);}const a=document.createElement('a');a.href=e.experiment_url;a.target='_blank';a.rel='noreferrer';a.className='trace-link';a.textContent='Inspect experiment in Braintrust ↗';details.append(a);$('extraControls').append(details);setText('clock',String(state.case+1).padStart(2,'0'));setText('duration','/ '+e.cases.length+' cases');$('seek').value=state.case;}
function controls(){const context=$('contextControls');context.replaceChildren();$('extraControls').replaceChildren();if(state.scene==='heart'||state.scene==='trail'){const label=document.createElement('label');label.htmlFor='workout';label.textContent='Choose a recorded session';const select=document.createElement('select');select.id='workout';select.setAttribute('aria-label','Recorded session');for(const [i,x] of state.data.workouts.entries())select.append(new Option(`${x.date} · ${x.activity} · ${x.distance?.toFixed(1)??'—'} km`,i));select.value=state.workout;select.onchange=e=>selectWorkout(e.target.value);context.append(label,select);if(state.scene==='heart'&&state.data.synthetic){const l=document.createElement('label');l.className='gap-control';const c=document.createElement('input');c.type='checkbox';c.checked=state.gap;c.id='gap';c.onchange=()=>{state.gap=c.checked;if(state.gap){state.time=650;setPlay(false);}update();};l.append(c,'Demonstrate a missing-signal interval');context.append(l);}}else if(state.scene==='agents'){const label=document.createElement('label');label.htmlFor='experiment';label.textContent='Compare a recorded experiment';const select=document.createElement('select');select.id='experiment';select.setAttribute('aria-label','Braintrust experiment');for(const [i,e] of state.braintrust.experiments.entries())select.append(new Option(`${e.variant} / ${e.planner} · ${Math.round(e.pass_rate*100)}%`,i));select.value=state.experiment;select.onchange=e=>{state.experiment=Number(e.target.value);state.case=0;drawCases();update();};context.append(label,select);const filters=document.createElement('div');filters.className='filters';for(const f of ['all','failed','blocked']){const b=document.createElement('button');b.textContent=f==='all'?'All cases':f==='failed'?'Failures':'Blocked';b.setAttribute('aria-pressed',String(f===state.filter));b.onclick=()=>{state.filter=f;const e=currentExperiment(),i=e.cases.findIndex(c=>f==='all'||f==='failed'&&!c.case_pass||f==='blocked'&&c.status==='blocked');if(i>=0)state.case=i;controls();drawCases();update();};filters.append(b);}context.append(filters);}}
function changeScene(scene){if(!SCENES.includes(scene))throw Error('Unknown scene');if(!state.data)return;if(scene==='agents'&&!state.braintrust){setText('status','Braintrust snapshot is unavailable.');return;}state.scene=scene;setPlay(false);for(const s of SCENES)$(s+'Scene').hidden=s!==scene;document.querySelectorAll('[data-scene]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.scene===scene)));const copy=scenes[scene];setText('chapter',copy.chapter);$('headline').innerHTML=copy.title;setText('intro',copy.intro);setText('sceneLabel',copy.label);setText('sceneContext',copy.context);const replay=scene==='heart'||scene==='trail';$('play').disabled=!replay;$('speed').disabled=!replay;$('seek').max=replay?(w?.duration||0):scene==='recovery'?Math.max(0,state.data.nights.length-1):39;setText('seekLabel',replay?'WORKOUT PLAYHEAD':scene==='recovery'?'SELECT A RECORDED NIGHT':'EXPLORE EVERY EVALUATION CASE');$('seek').setAttribute('aria-label',replay?'Workout time':scene==='recovery'?'Recorded night':'Evaluation case');setText('rangeStart',replay?'START':'FIRST');setText('rangeEnd',replay?'FINISH':'LATEST');if(scene==='trail')drawTrail();if(scene==='recovery')drawNights();if(scene==='agents')drawCases();controls();update();}
function update(){if(!state.data)return;if(state.scene==='heart'||state.scene==='trail'){setText('clock',clock(state.time));$('seek').value=state.time;setText('duration','/ '+clock(w?.duration));if(state.scene==='heart')updateHeart();else updateTrail();}else if(state.scene==='recovery')updateNight();else updateCase();}
function selectWorkout(value){const i=Number(value);if(!Number.isInteger(i)||!state.data.workouts[i])throw Error('Unknown workout');state.workout=i;w=state.data.workouts[i];state.time=0;state.gap=false;setPlay(false);$('seek').max=w.duration;if(state.scene==='trail')drawTrail();if($('gap'))$('gap').checked=false;update();}
function load(data){if(data.schema!==1||!Array.isArray(data.workouts)||!Array.isArray(data.nights))throw Error('Invalid snapshot');state.data=data;state.night=Math.max(0,data.nights.length-1);w=data.workouts[0];state.workout=0;state.time=0;state.gap=false;setText('sourceBadge',data.synthetic?'FICTIONAL DATA':'PERSONAL · LOCAL');setText('footerScope',data.synthetic?'Local-first • No account or model key needed':'Private local snapshot • Never sent to Braintrust');document.querySelector('footer>span').textContent=data.synthetic?'REAL PIPELINE. FICTIONAL ATHLETE.':'PRIVATE SNAPSHOT. LOCAL DISPLAY ONLY.';changeScene(state.scene);}
$('seek').addEventListener('input',e=>{const v=Number(e.target.value);if(state.scene==='recovery')state.night=v;else if(state.scene==='agents'){state.case=v;state.filter='all';controls();drawCases();}else state.time=v;update();});$('speed').onchange=e=>state.speed=Number(e.target.value);$('play').onclick=()=>{if(w&&state.time>=w.duration)state.time=0;setPlay(!state.playing);};$('motion').onclick=()=>setReduced(!state.reduced);setReduced(state.reduced);$('about').onclick=()=>$('info').showModal();$('closeInfo').onclick=()=>$('info').close();document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>changeScene(b.dataset.scene));
$('loadLocal').onclick=async()=>{try{const r=await fetch('/api/snapshot');if(!r.ok)throw Error();load(await r.json());$('loadLocal').hidden=true;setText('status','Local snapshot loaded. It remains on this machine.');}catch{setText('status','Start the Python server with --db to open a local snapshot.');}};
let lastPaint=0;function tick(t){const dt=state.last?Math.min((t-state.last)/1000,.2):0;state.last=t;if(w&&(state.scene==='heart'||state.scene==='trail')){if(state.playing){state.time=Math.min(w.duration,state.time+dt*state.speed);if(state.time>=w.duration)setPlay(false);if(t-lastPaint>100){update();lastPaint=t;}}const bpm=currentHR()?.bpm;$('heart').style.transform=`translate(-50%,-50%) scale(${beatScale(bpm,t/1000,state.playing&&!state.reduced)})`;if(state.scene==='trail'&&$('burro')){const p=sampleAt(w.route,state.time);const bob=state.playing&&!state.reduced&&p?.speed>.5?Math.sin(t/90)*2:0;$('burro').style.transform=`translate(-50%,-85%) translateY(${bob}px)`;}}requestAnimationFrame(tick);}requestAnimationFrame(tick);
async function init(){try{const [dr,br]=await Promise.all([fetch('demo.json'),fetch('braintrust.json')]);if(!dr.ok)throw Error('Demo unavailable');if(br.ok)state.braintrust=await br.json();const demo=await dr.json();if(demo.sessions)demo.workouts=await Promise.all(demo.sessions.map(async path=>{const r=await fetch(path);if(!r.ok)throw Error("Session unavailable");return r.json();}));load(demo);const initial=new URLSearchParams(location.search).get('scene');if(SCENES.includes(initial))changeScene(initial);if(['127.0.0.1','localhost'].includes(location.hostname)){$('loadLocal').hidden=false;}registerTools();}catch{$('empty').hidden=false;setText('status','Unable to load the snapshot. Start the local server and refresh.');$('play').disabled=true;}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const tool={name:'configure_atlas_view',description:'Select the visible scene, a workout replay time, and reduced-motion setting. Does not upload data or start playback.',inputSchema:{type:'object',properties:{scene:{type:'string',enum:SCENES},second:{type:'number',minimum:0},reducedMotion:{type:'boolean'}},required:['scene'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!SCENES.includes(input.scene)||input.second!==undefined&&(!Number.isFinite(input.second)||input.second<0||input.second>(w?.duration||0))||input.reducedMotion!==undefined&&typeof input.reducedMotion!=='boolean')throw Error('Invalid view configuration');changeScene(input.scene);if(input.second!==undefined)state.time=input.second;if(input.reducedMotion!==undefined)setReduced(input.reducedMotion);update();return {scene:state.scene,second:state.time,reducedMotion:state.reduced};}};try{Promise.resolve(context.registerTool(tool)).catch(()=>{});}catch{}}
window.addEventListener('resize',()=>{if(state.scene==='trail')updateTrail();});document.addEventListener('visibilitychange',()=>{state.last=0;});init();
